mapper.select:
SELECT item_id, name, category, sub_type, color, sub_colors, pattern, seasons, styles, formality, status, brand, worn_count, last_worn_at, purchased_at, purchased_at_estimated, created_at, retired_at, retire_reason, retire_memo FROM tb_wardrobe_item WHERE user_id = #{userId}
AND retired_at IS NOT NULL
AND retired_at IS NULL
AND category = #{category}
AND status = #{status}
AND (color = #{color} OR #{color} = ANY (sub_colors))
AND (name ILIKE #{queryPattern} ESCAPE '\' OR brand ILIKE #{queryPattern} ESCAPE '\')
ORDER BY worn_count DESC, last_worn_at DESC NULLS LAST, item_id DESC
ORDER BY lower(name) COLLATE "C" ASC, item_id ASC
ORDER BY created_at DESC, item_id DESC

SELECT item_id
  FROM tb_wardrobe_item
 WHERE user_id = #{userId}
   AND item_id IN
#{id}

SELECT count(*)
  FROM tb_wardrobe_item
 WHERE user_id = #{userId}
   AND retired_at IS NULL
   AND last_worn_at >= #{since}

SELECT count(*)
  FROM tb_wardrobe_item

    WHERE category = #{code}
    WHERE sub_type = #{code}
    WHERE color = #{code} OR #{code} = ANY (sub_colors)
    WHERE pattern = #{code}
    WHERE status = #{code}
    WHERE #{code} = ANY (seasons)
    WHERE #{code} = ANY (styles)
    WHERE retire_reason = #{code}
    WHERE FALSE
